                writer.WriteString("last_synced_uid", migrationMailbox.LastSyncedUid);

            if (migrationMailbox.LastSyncedAtOption.IsSet)
                writer.WriteString("last_synced_at", migrationMailbox.LastSyncedAtOption.Value!.Value.ToString(LastSyncedAtFormat));

            if (migrationMailbox.ErrorMessageOption.IsSet)
                writer.WriteString("error_message", migrationMailbox.ErrorMessage);

            if (migrationMailbox.StartedAtOption.IsSet)
                writer.WriteString("started_at", migrationMailbox.StartedAtOption.Value!.Value.ToString(StartedAtFormat));

            if (migrationMailbox.CompletedAtOption.IsSet)
                writer.WriteString("completed_at", migrationMailbox.CompletedAtOption.Value!.Value.ToString(CompletedAtFormat));
        }
    }
}
